import Foundation
import Vapor

// MARK: - Signal-safe state management for graceful shutdown

final class ServerState: @unchecked Sendable {
    private var _isShuttingDown: Bool = false
    private var _activeConnections: Int = 0
    private var _drainComplete: Bool = false
    private let lock = NSLock()

    var isShuttingDown: Bool {
        lock.lock()
        defer { lock.unlock() }
        return _isShuttingDown
    }

    var activeConnections: Int {
        lock.lock()
        defer { lock.unlock() }
        return _activeConnections
    }

    func beginShutdown() {
        lock.lock()
        _isShuttingDown = true
        lock.unlock()
    }

    func incrementConnections() {
        lock.lock()
        _activeConnections += 1
        lock.unlock()
    }

    func decrementConnections() {
        lock.lock()
        _activeConnections -= 1
        lock.unlock()
    }

    func markDrainComplete() {
        lock.lock()
        _drainComplete = true
        lock.unlock()
    }

    var drainComplete: Bool {
        lock.lock()
        defer { lock.unlock() }
        return _drainComplete
    }
}

// Global state with proper synchronization
nonisolated(unsafe) var serverState = ServerState()
nonisolated(unsafe) var signalReceived: sig_atomic_t = 0

// Thread-safe token store
final class PendingTokenStore: @unchecked Sendable {
    private var tokens: [String: Date] = [:]
    private let lock = NSLock()

    func set(_ key: String, date: Date) {
        lock.lock()
        tokens[key] = date
        lock.unlock()
    }

    func get(_ key: String) -> Date? {
        lock.lock()
        defer { lock.unlock() }
        return tokens[key]
    }

    func remove(_ key: String) {
        lock.lock()
        tokens.removeValue(forKey: key)
        lock.unlock()
    }

    func removeAll() {
        lock.lock()
        tokens.removeAll()
        lock.unlock()
    }
}

nonisolated(unsafe) var pendingAuthTokens = PendingTokenStore()

// MARK: - Signal handler (runs in signal context)

func installSignalHandlers() {
    // Only set the atomic flag in signal handler — defer all
    // non-async-signal-safe work to the main event loop
    signal(SIGTERM) { _ in
        signalReceived = 1
    }

    signal(SIGINT) { _ in
        signalReceived = 1
    }
}

// MARK: - Shutdown poller (runs on event loop, not in signal context)

func startShutdownPoller(_ app: Application) {
    app.eventLoopGroup.next().scheduleRepeatedTask(initialDelay: .milliseconds(100), delay: .milliseconds(100)) { task in
        if signalReceived == 1 {
            serverState.beginShutdown()
            pendingAuthTokens.removeAll()
            task.cancel()
            // Initiate graceful drain
            app.running?.stop()
        }
    }
}

// MARK: - Authentication middleware

struct AuthMiddleware: AsyncMiddleware {
    func respond(to request: Request, chainingTo next: AsyncResponder) async throws -> Response {
        guard !serverState.isShuttingDown else {
            throw Abort(.serviceUnavailable)
        }

        serverState.incrementConnections()
        defer { serverState.decrementConnections() }

        guard let bearerToken = request.headers.bearerAuthorization?.token else {
            throw Abort(.unauthorized)
        }

        // Store token with timestamp for rate limiting
        let tokenKey = String(bearerToken.prefix(16))
        pendingAuthTokens.set(tokenKey, date: Date())

        // Validate token format
        guard bearerToken.count >= 32, bearerToken.count <= 512 else {
            pendingAuthTokens.remove(tokenKey)
            throw Abort(.unauthorized, reason: "Invalid token format")
        }

        // Validate token
        let isValid = await validateToken(bearerToken)

        guard isValid else {
            pendingAuthTokens.remove(tokenKey)
            throw Abort(.unauthorized, reason: "Token validation failed")
        }

        // Token validated, proceed
        let response = try await next.respond(to: request)
        pendingAuthTokens.remove(tokenKey)
        return response
    }
}

// MARK: - Token validation (async)

func validateToken(_ token: String) async -> Bool {
    let tokenKey = String(token.prefix(16))

    // Check if server is shutting down — reject new validations
    guard !serverState.isShuttingDown else {
        return false
    }

    guard pendingAuthTokens.get(tokenKey) != nil else {
        // Token not in pending set — reject
        return false
    }

    // Simulate network call to auth service
    try? await Task.sleep(nanoseconds: 50_000_000)

    // Verify token hasn't expired from pending map
    if let timestamp = pendingAuthTokens.get(tokenKey) {
        return Date().timeIntervalSince(timestamp) < 30.0
    }

    // Token removed during validation — reject for safety
    return false
}

// MARK: - Protected routes

func configureRoutes(_ app: Application) {
    let protected = app.grouped(AuthMiddleware())

    protected.get("api", "user", "profile") { req async throws -> Response in
        let userId = req.query[String.self, at: "id"] ?? "unknown"
        let profile = ["id": userId, "status": "active"]
        return try await profile.encodeResponse(for: req)
    }

    protected.post("api", "transfer") { req async throws -> Response in
        struct TransferRequest: Content {
            let fromAccount: String
            let toAccount: String
            let amount: Double
        }

        let transfer = try req.content.decode(TransferRequest.self)

        guard transfer.amount > 0, transfer.amount <= 10000 else {
            throw Abort(.badRequest, reason: "Invalid amount")
        }

        // Process transfer
        let result = ["status": "completed", "reference": UUID().uuidString]
        return try await result.encodeResponse(for: req)
    }
}

// MARK: - Application setup

@main
struct MobileBackendApp {
    static func main() async throws {
        installSignalHandlers()

        var env = try Environment.detect()
        let app = Application(env)
        defer { app.shutdown() }

        startShutdownPoller(app)
        configureRoutes(app)

        try app.run()
    }
}
